/**
 * Curated OEM wheel/tire fitment reference data for common vehicles.
 *
 * A curated dataset of common US-market and German/Spanish-market vehicles. Rows were
 * re-verified in October 2026 against the regional OE fitment tables on wheel-size.com
 * (standard size, factory option sizes, PCD, center bore, fastener and torque), with
 * earlier manufacturer/service-manual sources retained where they agree. It is NOT a licensed OEM data
 * feed and is not exhaustive — trims and model years vary. `confidence` and
 * `sources` are kept per-entry so the UI can be honest about how solid each
 * number is, and so this can be corrected/expanded over time.
 *
 * Always cross-check against the vehicle's own manual before torquing wheels —
 * this is a starting reference, not a substitute for the OEM spec of the
 * specific trim in hand.
 */

export type FitmentConfidence = 'high' | 'medium' | 'low';
export type TorqueEvidence = 'documented' | 'unconfirmed' | 'extrapolated';

export interface WheelTorqueTrust {
  /** Confidence in the torque value specifically, independent of the rest of the row. */
  readonly confidence: FitmentConfidence;
  /** How directly the listed generation/trim supports the value. */
  readonly evidence: TorqueEvidence;
  /** Torque-specific sourcing caveat shown anywhere the value is presented. */
  readonly note?: string;
}

export interface VehicleFitment {
  readonly id: string;
  readonly make: string;
  readonly model: string;
  /** e.g. "2020–2024 (XII / E210)" */
  readonly generation: string;
  readonly market: 'us' | 'eu';
  /** e.g. "205/55R16" — the standard (base) factory size for the referenced trim. */
  readonly tireSize: string;
  /**
   * Further factory sizes (OE options on other trims or wheel packages) for the same
   * generation and market. Each one links this vehicle to its tire-size page, labelled as an
   * option rather than the standard size.
   */
  readonly optionalTireSizes?: readonly string[];
  /** e.g. "5x114.3" */
  readonly boltPattern: string;
  /**
   * Lug count, restating the first half of `boltPattern`. It is cross-checked against the
   * notation at catalog build time (see buildBoltPatternCatalog) so the two can never drift.
   *
   * There is deliberately NO stored hole-to-hole spacing field here. Adjacent-hole spacing is
   * a function of the bolt pattern (PCD × sin(π / lugs)) and is derived on demand via
   * adjacentHoleSpacingMm() / boltPatternSpacingMm() in ./bolt-pattern-geometry, so it can
   * never be hand-typed as a duplicate of the PCD and can never disagree with `boltPattern`.
   */
  readonly lugCount: number;
  readonly centerBoreMm?: number;
  /** e.g. "17x7.5" */
  readonly wheelSize: string;
  readonly torqueNm?: number;
  readonly torqueLbFt?: number;
  /** Required whenever a torque value is present. */
  readonly torqueTrust?: WheelTorqueTrust;
  readonly fastenerType: 'lug-nut' | 'wheel-bolt';
  readonly confidence: FitmentConfidence;
  readonly sources: readonly string[];
  /** English note. German/Spanish pages only show a note in their own language. */
  readonly notes?: string;
  readonly notesDe?: string;
  readonly notesEs?: string;
}

/** The note in the reader's language, or nothing — never an English note on a DE/ES page. */
export function vehicleNote(vehicle: VehicleFitment, locale: 'en' | 'de' | 'es' | 'fr'): string | undefined {
  return locale === 'de' ? vehicle.notesDe : locale === 'es' ? vehicle.notesEs : vehicle.notes;
}

